test('C-02-05/06 dado fixture completa quando smoke é executado então percorre proxy, health, PEC e CH off sem vazar segredo', () => {
  const stateDir = mkdtempSync(join(tmpdir(), 'detran-smoke-contract-'));
  try {
    const source = `
      import { readFileSync, readdirSync } from 'node:fs';
      import { runSmoke } from ${JSON.stringify(smokePath)};
      const targets = ${JSON.stringify(smokeFixture)};
      const calls = [];
      const response = (body, status = 200, headers = { 'content-type': 'application/json' }) => new Response(typeof body === 'string' ? body : JSON.stringify(body), { status, headers });
      const fetchImpl = async (url, init = {}) => {
        const value = String(url); calls.push({ url: value, headers: Object.fromEntries(new Headers(init.headers).entries()) });
        if (value.includes('/v1/')) return response({ tenantId: targets.frontends[0].expectedTenant, items: [{ id: 'fixture-001' }], layer: 'N1' });
        if (value.endsWith('/healthz') || value.endsWith('/readyz') || value.endsWith(':3000/health') || value.endsWith(':3999/health')) return response({ status: 'ok', message: 'healthy' });
        return response({ status: 'ok' });
      };
      const report = await runSmoke({ targets, fetchImpl });
      if (report.complete !== true) throw new Error('complete smoke report required');
      const proxyCalls = calls.filter(({ url }) => url.includes('/v1/'));
      if (proxyCalls.length !== 4) throw new Error('four proxy reads required');
      for (const call of proxyCalls) {
        if (!call.headers.authorization || call.headers.authorization !== 'Bearer local') throw new Error('proxy Authorization header required');
        if (call.url.includes(':3001')) throw new Error('proxy read bypassed frontend');
      }
      for (const path of ['/healthz', '/readyz']) if (!calls.some(({ url }) => url === 'http://127.0.0.1:3001' + path)) throw new Error(path + ' not checked');
      if (report.pec?.state !== 'not_built_r0031' && report.targets?.pec?.state !== 'not_built_r0031') throw new Error('PEC must be not_built_r0031');
      const files = readdirSync(${JSON.stringify(stateDir)});
      for (const file of files) {
        const text = readFileSync(${JSON.stringify(stateDir)} + '/' + file, 'utf8');
        if (/token|bearer|password|secret|:\/\/[^/\\s:@]+:[^@\\s]+@/i.test(text)) throw new Error('secret in smoke evidence');
      }
      if (!calls.some(({ url }) => url.endsWith(':3000/health')) || !calls.some(({ url }) => url.endsWith(':3999/health'))) throw new Error('adapter healths not checked');
    `;
    const result = runSmokeChild(source, { DETRAN_STACK_STATE_DIR: stateDir });
    assert.equal(result.status, 0, result.stderr || result.stdout);
  } finally {
    rmSync(stateDir, { recursive: true, force: true });
  }
});

